// src/components/Navbar.jsx
import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  return (
    <nav className="bg-slate-900 text-white px-6 py-4 flex justify-between items-center shadow">
      <div className="flex items-center space-x-6">
        <Link to="/" className="text-xl font-bold text-blue-400">CarRental</Link>
        <Link to="/cars" className="hover:text-blue-300">รถเช่าทั้งหมด</Link>
        {user && (
          <>
            <Link to="/my-bookings" className="hover:text-blue-300">การจองของฉัน</Link>
            <Link to="/profile" className="hover:text-blue-300">โปรไฟล์</Link>
          </>
        )}
        {user?.role === 'admin' && (
          <Link to="/admin" className="bg-amber-500 text-slate-900 px-3 py-1 rounded font-semibold text-sm">
            จัดการระบบ (Admin)
          </Link>
        )}
      </div>

      <div className="flex items-center space-x-4">
        {user ? (
          <>
            <span className="text-sm text-gray-300">สวัสดี, {user.full_name}</span>
            <button onClick={handleLogout} className="bg-red-600 px-3 py-1.5 rounded text-sm hover:bg-red-700">
              ออกจากระบบ
            </button>
          </>
        ) : (
          <>
            <Link to="/login" className="hover:text-blue-300 text-sm">เข้าสู่ระบบ</Link>
            <Link to="/register" className="bg-blue-600 px-4 py-1.5 rounded text-sm hover:bg-blue-700">
              สมัครสมาชิก
            </Link>
          </>
        )}
      </div>
    </nav>
  );
}
